"""Curriculum and industry-project definitions for the academy."""

BASE_WEEKS = [(1, 'Platform Foundation', 'Salesforce Platform and CRM Fundamentals', 'CRM concepts, Salesforce architecture, multitenancy, metadata versus data, standard and custom objects, org types, Setup, Object Manager, and Schema Builder.', 'Build a customer onboarding or loan application data model using Account, Contact, Application, Document, Review, and Offer.', 'How Salesforce multitenancy affects application design, governor limits, metadata-driven architecture, and shared platform resources.', 'Salesforce is more than a CRM: what metadata-driven development means.'), (2, 'Platform Foundation', 'Data Modeling and Data Quality', 'Lookup and master-detail relationships, junction objects, formulas, roll-up summaries, validation rules, external IDs, record types, Dynamic Forms, duplicate rules, and matching rules.', 'Enhance the Week 1 model with validation, duplicate prevention, formulas, record types, a junction object, and conditional field visibility.', 'Lookup versus master-detail relationships, including ownership, deletion, sharing, roll-ups, and reparenting.', 'One relationship-design decision that can affect an entire Salesforce solution.'), (3, 'Platform Foundation', 'Security and Access Control', 'Profiles, permission sets, permission set groups, OWD, role hierarchy, sharing rules, object permissions, field-level security, record access, least privilege, and audit tools.', 'Create Sales Representative, Underwriter, and Manager personas with documented access boundaries.', 'How Salesforce security layers work together across object, field, and record access.', 'Salesforce security is not controlled by one setting.'), (4, 'Platform Foundation', 'Flow and Declarative Automation', 'Before-save flows, after-save flows, screen flows, scheduled flows, subflows, invocable Apex, fault paths, order of execution, recursion, and automation selection.', 'Build one before-save flow, one after-save flow, one screen flow, and one scheduled flow with fault handling.', 'Flow versus Apex, including formulas, validation rules, record-triggered Flow, scheduled Flow, and invocable Apex.', 'Not every Salesforce automation requires Apex.'), (5, 'Core Development', 'Development Environment and Salesforce DX', 'VS Code, Salesforce Extension Pack, Salesforce CLI, project structure, org authorization, aliases, metadata retrieval, deployments, source tracking, scratch orgs, sandboxes, manifests, and package directories.', 'Create a Salesforce DX project, connect an org, retrieve metadata, deploy a change, and commit it to Git.', 'Source-driven Salesforce development and the differences among scratch orgs, sandboxes, and Developer Edition orgs.', 'Why modern Salesforce developers should learn Salesforce CLI.'), (6, 'Core Development', 'Apex Programming Fundamentals', 'Variables, data types, collections, conditions, loops, methods, classes, constructors, interfaces, inheritance, exceptions, null handling, and object-oriented programming.', 'Build an Apex scoring service that validates inputs and returns a structured result without database access.', 'Object-oriented programming in Apex and why separation of responsibilities matters.', 'Apex is more than syntax.'), (7, 'Core Development', 'SOQL, SOSL, and Data Access', 'SOQL, SOSL, relationship queries, aggregate queries, bind variables, dynamic SOQL, selectivity, query planning, indexes, governor limits, and bulk processing.', 'Write queries for related records, aggregates, missing data, duplicate applicants, and large-volume scenarios.', 'Efficient SOQL design, selective queries, large data volumes, and the Query Plan Tool.', 'Why SOQL inside a loop is a serious Salesforce development mistake.'), (8, 'Core Development', 'Apex Triggers and Service Architecture', 'Trigger contexts, before and after operations, bulkification, recursion, handler classes, service classes, transaction boundaries, savepoints, and rollback.', 'Build a bulk-safe application review automation using one trigger and supporting classes.', 'Trigger architecture patterns, handlers, services, recursion control, and change detection.', 'A trigger should coordinate work instead of containing the entire application.'), (9, 'Core Development', 'Apex Security', 'with sharing, without sharing, inherited sharing, CRUD, FLS, user mode, system mode, secure dynamic SOQL, validation, injection prevention, and sensitive-data handling.', 'Review and rewrite an intentionally insecure Apex class.', 'User mode, system mode, sharing, CRUD, and field-level security in Apex.', 'Why with sharing does not enforce every Salesforce security layer.'), (10, 'Core Development', 'Apex Testing', 'Test isolation, test data factories, @TestSetup, positive and negative tests, bulk tests, permission tests, asynchronous tests, callout mocks, assertions, and meaningful coverage.', 'Write behavior-focused tests for Week 8 automation, including bulk, permissions, duplicate prevention, and exceptions.', 'What makes an Apex test valuable beyond code coverage.', 'Code coverage does not prove that Salesforce code works correctly.'), (11, 'Core Development', 'Asynchronous Apex and Integrations', 'Future, Queueable, Batch, Scheduled Apex, Platform Events, Change Data Capture, REST callouts, JSON, Named Credentials, retry design, idempotency, logging, and recovery.', 'Build a mock external verification process using Queueable Apex, a callout mock, logging, and safe retries.', 'Queueable Apex versus Batch Apex versus Platform Events.', 'Choosing the correct asynchronous tool in Salesforce.'), (12, 'Core Development', 'Lightning Web Components Fundamentals', 'HTML, CSS, modern JavaScript, modules, promises, async and await, LWC structure, reactivity, getters, events, conditional rendering, lists, base components, and SLDS.', 'Build an application summary component with status, risk, and missing-document indicators.', 'How Lightning Web Components use modern web standards.', 'One JavaScript concept that became important while learning LWC.'), (13, 'Core Development', 'LWC Data and Component Communication', 'Lightning Data Service, UI Record API, wire service, imperative Apex, caching, parent-child communication, custom events, Lightning Message Service, navigation, toasts, and loading states.', 'Build a review workbench with multiple communicating components and user-friendly error handling.', 'Lightning Data Service versus custom Apex controllers.', 'Not every LWC requires a custom Apex controller.'), (14, 'Core Development', 'Advanced LWC and User Experience', 'Composition, reusable utilities, custom data tables, forms, validation, file upload, accessibility, responsive design, debouncing, performance, and Jest fundamentals.', 'Create a reusable document-management component with search, categories, upload, permissions, and responsive behavior.', 'LWC performance and accessibility.', 'A component is not complete merely because it works.'), (15, 'Engineering Practices', 'Git and Team Development', 'Repositories, branches, commits, pull requests, merge conflicts, code review, protected branches, reverting, .gitignore, and secrets management.', 'Complete a feature branch workflow with focused commits, a pull request, review feedback, conflict resolution, and merge.', 'Git workflows for Salesforce teams.', 'A good Git commit should tell a story.'), (16, 'Engineering Practices', 'Deployment and DevOps', 'Development lifecycle, source-driven releases, CLI deployments, DevOps Center, continuous integration, validation deployments, dependencies, destructive changes, rollback planning, and post-deployment steps.', 'Prepare and validate a release containing Apex, tests, LWC, fields, permissions, and Flow.', 'Continuous integration and Salesforce deployment reliability.', 'Deployment success does not always mean release success.'), (17, 'Engineering Practices', 'Debugging, Monitoring, and Code Quality', 'Debug logs, Developer Console, Apex Replay Debugger, Flow failures, limits, permissions, integration failures, static analysis, Code Analyzer, technical debt, and root-cause analysis.', 'Diagnose a multi-layer broken feature and produce a root-cause report.', 'Structured root-cause analysis across Apex, Flow, LWC, permissions, and integrations.', 'Debugging should begin with evidence rather than guesses.'), (18, 'AI and Agents', 'AI-Assisted Salesforce Development', 'LLM limitations, prompts, context windows, hallucinations, privacy, secure context, AI-generated code review, deterministic versus probabilistic systems, and verification workflows.', 'Use an AI coding assistant to produce an Apex service, then identify and correct issues involving security, bulkification, null handling, testing, and maintainability.', 'Benefits and risks of AI-generated Salesforce code.', 'AI can generate code, but it cannot own the consequences.'), (19, 'AI and Agents', 'MCP Servers, Tools, CLI, and Agent Skills', 'Model Context Protocol, clients, servers, tools, resources, authentication, Salesforce DX MCP Server, tool discovery, least privilege, context management, MCP versus APIs, MCP versus CLI, skills, project instructions, and scripts.', 'Configure an approved development agent to inspect metadata, query an org, run tests, run code analysis, retrieve metadata, and explain a deployment diff.', 'MCP servers versus APIs versus Salesforce CLI, plus the difference among tools, skills, scripts, and instructions.', 'MCP gives an agent tools, while skills teach it how the team wants work performed.'), (20, 'AI and Agents', 'Agentforce Development', 'Agentforce fundamentals, instructions, actions, Flow actions, Apex actions, prompt templates, Agent Script, Agentforce DX, grounding, guardrails, testing, Agent API, headless agents, deployment, monitoring, and escalation.', 'Build an internal application-review agent that summarizes records, identifies missing documents, triggers approved actions, refuses unauthorized actions, and escalates unsupported requests.', 'Designing secure and reliable Salesforce agents.', 'A Salesforce agent needs clearly defined authorization boundaries.')]

PROJECTS = [{'number': 1, 'industry': 'Financial Services', 'title': 'Lending Operations & Underwriting App', 'summary': 'A secure application for applicants, documents, underwriting reviews, offers, and approval workflows.', 'final_deliverable': 'A working declarative lending operations application with a complete data model, data-quality controls, persona-based security, automated underwriting workflow, reports, and a recorded demonstration.', 'week_start': 1, 'week_end': 4, 'accent': 'finance'}, {'number': 2, 'industry': 'Healthcare', 'title': 'Patient Referral & Care Coordination App', 'summary': 'A source-driven healthcare application that coordinates referrals, eligibility, care tasks, and patient follow-up.', 'final_deliverable': 'A source-controlled healthcare referral application with Apex services, efficient data access, bulk-safe automation, tests, documentation, and a live demonstration.', 'week_start': 5, 'week_end': 8, 'accent': 'healthcare'}, {'number': 3, 'industry': 'Nonprofit', 'title': 'Donor & Volunteer Engagement App', 'summary': 'An engagement application for donors, campaigns, volunteers, acknowledgements, and external-service coordination.', 'final_deliverable': 'A secure nonprofit engagement application with user-mode Apex, automated tests, asynchronous integration, an LWC engagement dashboard, and a stakeholder demonstration.', 'week_start': 9, 'week_end': 12, 'accent': 'nonprofit'}, {'number': 4, 'industry': 'Manufacturing', 'title': 'Order & Inventory Operations App', 'summary': 'An operations workspace for customers, orders, inventory exceptions, documents, fulfillment, and release management.', 'final_deliverable': 'A responsive manufacturing operations application with communicating LWCs, inventory and document workflows, Git history, deployment validation, release notes, and a production-readiness review.', 'week_start': 13, 'week_end': 16, 'accent': 'manufacturing'}, {'number': 5, 'industry': 'Professional Services', 'title': 'AI-Enabled Client Delivery App', 'summary': 'A client-delivery workspace enhanced with diagnostics, responsible AI assistance, MCP tooling, and Agentforce.', 'final_deliverable': 'A monitored client-delivery application with a documented debugging model, verified AI-assisted code, an approved MCP workflow, an Agentforce coordinator, guardrails, tests, and an executive demonstration.', 'week_start': 17, 'week_end': 20, 'accent': 'services'}]

